scwin.checkEl = function(id) {
    if (WebSquare.wUnit.getJq(id).attr("opened")) {
        return false;
    }
    return true;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script 탭 또는 Source 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //1. In the Script tab or the Source tab, check the scwin.trigger1_onclick section.
    //Test 2. 브라우저에서 '메뉴추가' 버튼을 클릭한다. 
    //In your browser, click the 'Add Menu' button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 메뉴가 추가된다. (그전버전에서는 메뉴추가시 닫혀있던 노드들이 열리는 현상이 발생함.)
    //A menu is added. (In the previous version, when the menu was added, the closed nodes were opened.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#treeview_group_3').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('#treeview_node_1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('#treeview_node_9')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 30-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
